import { useMemo } from 'react';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { TokenItemType, TokenDetailType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';

export const useTokenDetailType = (item: TokenItem) => {
  const tokenDetailType = useMemo(() => {
    if (item.type === TokenItemType.DC2) {
      if (item.bankCd === appConfig.BANK_CODE) {
        return TokenDetailType.DC2_당행;
      }
      return TokenDetailType.DC2_타행;
    }
    return TokenDetailType.DC1;
  }, [item.type]);
  return { tokenDetailType };
};
