import { useMutation } from '@tanstack/react-query';
import { UserResponse, UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { DeleteWalletRequestDTO, DeleteWalletResponseDTO } from '~/entities/wallet/api/dtos/delete-wallet';
import { walletApi } from '~/entities/wallet/api/wallet-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { snackBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';

const syncDeletedWalletCache = (deletedWalletId?: string) => {
  const queryClient = getGlobalQueryClient();
  const walletListQueryKey = queries.cstr.cstmrWalletList.queryKey;
  const userQueryKey = queries.cstr.cstmr({ cstmrNo: 'detail' }).queryKey;
  const prevUser = queryClient.getQueryData<UserResponse>(userQueryKey);
  const prevWalletList = queryClient.getQueryData<UserWalletResponse[]>(walletListQueryKey) ?? [];
  const deletedWallet = prevWalletList.find((wallet) => wallet.walletId === deletedWalletId);
  const remainingWalletList = prevWalletList.filter((wallet) => wallet.walletId !== deletedWalletId);
  const nextWallet = remainingWalletList[0];

  const nextPrimaryAlias =
    prevUser?.tbCstmrMastr?.priAliasNm === deletedWallet?.aliasNm ? null : prevUser?.tbCstmrMastr?.priAliasNm ?? null;
  const nextDefaultAlias =
    prevUser?.tbCstmrMastr?.dfltAliasNm === deletedWallet?.aliasNm
      ? nextWallet?.aliasNm ?? null
      : prevUser?.tbCstmrMastr?.dfltAliasNm ?? nextWallet?.aliasNm ?? null;

  queryClient.setQueryData<UserWalletResponse[]>(walletListQueryKey, () =>
    remainingWalletList.map((wallet) => ({
      ...wallet,
      priAliasNm: nextPrimaryAlias,
      dfltAliasNm: nextDefaultAlias,
    })),
  );

  setUserRes((prev) => ({
    ...prev,
    tbCstmrMastr: {
      ...prev.tbCstmrMastr,
      walletId: nextWallet?.walletId ?? '',
      aliasNm: nextWallet?.aliasNm ?? '',
      walletAliasNm: nextWallet?.walletAliasNm ?? '',
      realAcnutNo: nextWallet?.realAcnutNo ?? '',
      acnutno: nextWallet?.acnutno ?? prev.tbCstmrMastr.acnutno,
      acnutnoBlce: nextWallet?.acnutnoBlce ?? 0,
      bankCd: nextWallet?.bankCd ?? '',
      bankNm: nextWallet?.bankNm ?? '',
      priAliasNm: nextPrimaryAlias,
      dfltAliasNm: nextDefaultAlias,
      hasWallet: remainingWalletList.length > 0,
    },
  }));

  return remainingWalletList;
};

export const useDeleteWalletMutation = (
  options?: MutationOptions<DeleteWalletRequestDTO, CBDCAxiosError, DeleteWalletResponseDTO>,
) => {
  const { navigate } = useNavigate();
  const { openAlertDialog } = useAlertDialog();
  const { onSuccess, ...mutationOptions } = options ?? {};

  const mutation = useMutation<DeleteWalletResponseDTO, CBDCAxiosError, DeleteWalletRequestDTO>({
    ...mutationOptions,
    mutationFn: walletApi.deleteWallet,
    onSuccess: async (data, variables, onMutateResult, context) => {
      await onSuccess?.(data, variables, onMutateResult, context);
      if (!data.result) {
        return;
      }

      const deletedWalletId = variables.tbCstmrMastr.walletId;
      const remainingWalletList = syncDeletedWalletCache(deletedWalletId);

      snackBar(i18n.t('text:walletDeleteSuccess'));

      if (remainingWalletList.length === 0) {
        openAlertDialog({
          message: '보유한 지갑이 없어 Super APP 으로 이동합니다.',
          onConfirmClick: () => {
            window.location.replace(PATHS.superAppSample);
          },
        });
        return;
      }

      navigate(PATHS.home, { replace: true });
    },
  });

  return mutation;
};
